set -euo pipefail
upload_dir=$(getent passwd "$SUDO_USER" | cut -d: -f6)
cd /opt/news-flow/current
chown news-flow:news-flow /var/lib/news-flow/qc-remaining27-all-20261122/nhansac-all-posts.json
runuser -u news-flow -- /opt/news-flow/node/bin/node --input-type=module - <<'NODE'
import fs from 'node:fs';import {gzipSync} from 'node:zlib';import {createHash} from 'node:crypto';import {loadNewsRegistry} from './src/newsFlow/registry.mjs';import {NewsHttpDriver,NewsProxyPool} from './src/newsFlow/transport.mjs';import {NewsNetworkPool} from './src/newsFlow/networkPool.mjs';import {createRequire} from 'node:module';const require=createRequire('/opt/news-flow/current/package.json'),ch=require('cheerio'),root='/var/lib/news-flow/qc-remaining27-all-20261122',registry=await loadNewsRegistry(),pool=await NewsProxyPool.load('/etc/news-flow/proxies.json',{rotation:'request'}),network=new NewsNetworkPool({workers:1}),driver=new NewsHttpDriver({state:{cacheResponses:false,failedUrl:()=>false,request:()=>null,reserve:()=>true,cache:()=>null,completeHttpResponse:()=>{}},network,pool,allowedDomains:registry.allowedDomains,siteCooldown:false,maxWireRequests:3}),url='https://nhansac.vn/?rest_route=/wp/v2/posts&per_page=100&_fields=id,link,date_gmt,title,content,excerpt,status';try{let p=await driver.get('qc27-nhansac-all',url,registry.sources.get('nhansac.vn').config,[],{reviewFailed:true,taskRole:'publisher_dependency'});if(p.error==='ECONNREFUSED')p=await driver.get('qc27-nhansac-all-second-control',url,registry.sources.get('nhansac.vn').config,[],{reviewFailed:true,taskRole:'publisher_dependency'});const out={at:new Date().toISOString(),url,error:p.error,statusCode:p.statusCode};if(!p.error&&p.html){out.file=root+'/evidence/'+createHash('sha256').update(p.html).digest('hex')+'.gz';fs.writeFileSync(out.file,gzipSync(p.html));out.posts=JSON.parse(p.html).map(p=>{const $=ch.load(p.content?.rendered||''),text=$.text().replace(/\s+/g,' ').trim();return {id:p.id,link:p.link,date_gmt:p.date_gmt,status:p.status,title:ch.load(p.title.rendered).text(),chars:text.length,hash:createHash('sha256').update(text).digest('hex'),text:text.slice(0,1200)};});}fs.writeFileSync(root+'/nhansac-all-posts.json',JSON.stringify(out,null,2));console.log(JSON.stringify(out));}finally{await network.close();}
NODE
install -o "$SUDO_USER" -m 0600 /var/lib/news-flow/qc-remaining27-all-20261122/nhansac-all-posts.json "$upload_dir/.qc27-nhansac-all-posts.json"
